"""Demo: Dirichlet-energy identity and positive semidefiniteness.

Verifies, for a Hodge Laplacian L = B^T B, that the quadratic form <x, L x>
equals ||B x||^2 (a sum of squares), and is therefore always nonnegative.
"""
from __future__ import annotations
from typing import List

Vector = List[float]
Matrix = List[List[float]]


def dot(u: Vector, v: Vector) -> float:
    return sum(a * b for a, b in zip(u, v))


def transpose(A: Matrix) -> Matrix:
    return [list(c) for c in zip(*A)]


def matvec(A: Matrix, x: Vector) -> Vector:
    return [dot(row, x) for row in A]


def matmul(A: Matrix, B: Matrix) -> Matrix:
    Bt = transpose(B)
    return [[dot(r, c) for c in Bt] for r in A]


def hodge(B: Matrix) -> Matrix:
    return matmul(transpose(B), B)


def main() -> None:
    B = [[-1.0, 0.0, 1.0], [1.0, -1.0, 0.0], [0.0, 1.0, -1.0]]  # triangle loop
    L = hodge(B)
    for x in ([1.0, 0.0, 0.0], [2.0, -1.0, 3.0]):
        energy = dot(x, matvec(L, x))
        bx = matvec(B, x)
        print(f"x={x}: <x,Lx>={energy:.4f}, ||Bx||^2={dot(bx,bx):.4f}, "
              f"nonneg={energy >= -1e-12}")


if __name__ == "__main__":
    main()

"""Demo: harmonic signals are immortal under message passing.

On the triangle loop, the circulating signal (1,1,1) is harmonic (L x = 0).
We confirm it is a fixed point at every depth k of mpStep(x) = x - alpha*(L x).
"""
from __future__ import annotations
from typing import List

Vector = List[float]
Matrix = List[List[float]]


def dot(u: Vector, v: Vector) -> float:
    return sum(a * b for a, b in zip(u, v))


def transpose(A: Matrix) -> Matrix:
    return [list(c) for c in zip(*A)]


def matvec(A: Matrix, x: Vector) -> Vector:
    return [dot(r, x) for r in A]


def matmul(A: Matrix, B: Matrix) -> Matrix:
    Bt = transpose(B)
    return [[dot(r, c) for c in Bt] for r in A]


def mp_step(L: Matrix, alpha: float, x: Vector) -> Vector:
    Lx = matvec(L, x)
    return [xi - alpha * li for xi, li in zip(x, Lx)]


def main() -> None:
    B = [[-1.0, 0.0, 1.0], [1.0, -1.0, 0.0], [0.0, 1.0, -1.0]]
    L = matmul(transpose(B), B)
    x = [1.0, 1.0, 1.0]
    alpha = 0.3
    for k in (1, 10, 100, 1000):
        xk = x[:]
        for _ in range(k):
            xk = mp_step(L, alpha, xk)
        drift = sum((a - b) ** 2 for a, b in zip(xk, x)) ** 0.5
        print(f"depth {k:>5}: ||mpStep^k(x) - x|| = {drift:.3e}")


if __name__ == "__main__":
    main()
